import { catalog } from './engine.mjs';
import { examples as analogExamples } from './examples.mjs';
import { digitalExamples, fbdExamples } from './digital.mjs';
const examples=[...analogExamples.map(e=>({...e,mode:'analog'})),...digitalExamples,...fbdExamples];
let workspaceMode='analog',playSpeed=1,liveTimer;
const modeNames={analog:'Elektrické obvody',digital:'Číslicová technika',fbd:'FBD · funkční bloky'};
const allowed=c=>workspaceMode==='analog'?!c.modes:c.modes?.includes(workspaceMode);
const modeOf=p=>p.mode|| (p.components.some(c=>meta(c.type)?.mode==='fbd')?'fbd':p.components.some(c=>meta(c.type)?.modes)?'digital':'analog');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
const colors=['#e6b547','#65c4e1','#cd94ed','#7ccc9e','#e88e83','#a9b5f5'];
const storageKey='shieldio-simulation-v1';
const empty=()=>({version:1,mode:workspaceMode,title:'Nový obvod',components:[],wires:[],probes:[],settings:{duration:.01,step:.000005,acStart:10,acStop:100000,acPoints:180}});
let project=empty(),tool='select',placing=null,selected=null,wireStart=null,category='Vše',tab='scope',history=[],future=[],result=null,dcResult=null,running=false,busy=false,playback=0,lastFrame=0,raf=0,dirty=false;
let camera={x:0,y:0,zoom:1},drag=null,mouse={x:0,y:0},toastTimer,autoTimer;
let faultIds=[];let solverWorker=null,solverPending=null,solverSequence=0,instantResult=null;
function runSolver(payload){return new Promise((resolve,reject)=>{solverWorker?.terminate();solverWorker=new Worker(new URL('./solver-worker.mjs',import.meta.url),{type:'module'});let id=++solverSequence;solverPending={resolve,reject};solverWorker.onmessage=({data})=>{if(data.id!==id)return;solverPending=null;solverWorker.terminate();solverWorker=null;if(data.error)reject(Error(data.error));else resolve(data.result);};solverWorker.onerror=e=>{solverPending=null;solverWorker?.terminate();solverWorker=null;reject(Error(e.message||'Výpočetní jádro se nenačetlo.'));};solverWorker.postMessage({...payload,id});});}
function cancelSolver(){solverWorker?.terminate();solverWorker=null;if(solverPending){solverPending.reject(Error('Výpočet zastaven.'));solverPending=null;}}
const displayed=()=>tab==='scope'&&instantResult?instantResult:dcResult;
const svg=$('#schematic'),scene=$('#scene'),preview=$('#preview');
const meta=type=>catalog.find(c=>c.type===type);
const uid=prefix=>prefix+Math.random().toString(36).slice(2,9);
const snap=v=>Math.round(v/20)*20;
const key=p=>`${Math.round(p.x)},${Math.round(p.y)}`;
function fmt(v,unit='',digits=3){if(!Number.isFinite(v))return '—';if(v===0)return `0${unit?' '+unit:''}`;let prefixes=[[1e12,'T'],[1e9,'G'],[1e6,'M'],[1e3,'k'],[1,''],[1e-3,'m'],[1e-6,'µ'],[1e-9,'n'],[1e-12,'p'],[1e-15,'f']];let [scale,prefix]=prefixes.find(([n])=>Math.abs(v)>=n)||prefixes.at(-1);return `${Number((v/scale).toPrecision(digits))} ${prefix}${unit}`.trim();}
function numeric(s){if(typeof s==='number')return s;if(typeof s!=='string')throw Error('Zadejte číselnou hodnotu.');s=s.trim().replace(',','.');const m=s.match(/^([+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?)\s*(meg|[TGMkmunpµμf]?)(?:\s*(?:Ω|ohm|V|A|F|H|Hz|s|V\/s))?$/i);if(!m)throw Error(`Neplatná hodnota „${s}“. Použijte například 4.7k, 100n nebo 1e6.`);let p=m[2];if(p==='K')p='k';let scale=p==='M'||p.toLowerCase()==='meg'?1e6:({T:1e12,G:1e9,k:1e3,m:1e-3,u:1e-6,µ:1e-6,μ:1e-6,n:1e-9,p:1e-12,f:1e-15,'':1}[p]);let v=Number(m[1])*scale;if(!Number.isFinite(v))throw Error('Hodnota musí být konečné číslo.');return v;}
function toast(text,error=false){clearTimeout(toastTimer);let el=$('#toast');el.textContent=text;el.className='toast'+(error?' error':'');el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,error?10000:4500);}
function snapshot(){history.push(JSON.stringify(project));if(history.length>80)history.shift();future=[];}
function changed(resetResults=true){if(resetResults){faultIds=[];stop();result=null;dcResult=null;instantResult=null;dirty=true;}$('#title').value=project.title;$('#savedStatus').textContent='Ukládání…';clearTimeout(autoTimer);autoTimer=setTimeout(()=>{try{localStorage.setItem(storageKey,JSON.stringify(project));localStorage.setItem(storageKey+'-'+workspaceMode,JSON.stringify(project));$('#savedStatus').textContent='Uloženo v tomto prohlížeči';}catch{$('#savedStatus').textContent='Prohlížeč nemohl uložit projekt';}},250);render();}
function undo(){if(!history.length)return;future.push(JSON.stringify(project));project=JSON.parse(history.pop());workspaceMode=modeOf(project);applyMode();selected=null;changed();}
function redo(){if(!future.length)return;history.push(JSON.stringify(project));project=JSON.parse(future.pop());workspaceMode=modeOf(project);applyMode();selected=null;changed();}
function localPins(c){return (meta(c.type)?.pins||[]).filter(p=>c.type!=='opamp'||c.params?.powered||!['vcc','vee'].includes(p.id)).map(p=>{let r=(c.rotation||0)*Math.PI/180;return {...p,x:snap(c.x+p.x*Math.cos(r)-p.y*Math.sin(r)),y:snap(c.y+p.x*Math.sin(r)+p.y*Math.cos(r))};});}
function bounds(){let ps=[...project.components.flatMap(c=>[...localPins(c),{x:c.x-60,y:c.y-60},{x:c.x+70,y:c.y+65}]),...project.wires.flatMap(w=>[w.a,w.b]),...project.probes];if(!ps.length)return {x:0,y:0,w:900,h:500};let xs=ps.map(p=>p.x),ys=ps.map(p=>p.y),x=Math.min(...xs)-40,y=Math.min(...ys)-35;return {x,y,w:Math.max(...xs)-x+40,h:Math.max(...ys)-y+35};}
function fit(){let b=bounds(),rect=svg.getBoundingClientRect();camera.zoom=Math.min(1.45,Math.max(.18,Math.min(rect.width/b.w,rect.height/b.h)));camera.x=b.x-(rect.width/camera.zoom-b.w)/2;camera.y=b.y-(rect.height/camera.zoom-b.h)/2;applyCamera();}
function applyCamera(){let r=svg.getBoundingClientRect();svg.setAttribute('viewBox',`${camera.x} ${camera.y} ${r.width/camera.zoom} ${r.height/camera.zoom}`);$('#zoomLabel').textContent=Math.round(camera.zoom*100)+' %';}
function world(e){let r=svg.getBoundingClientRect();return {x:camera.x+(e.clientX-r.left)/camera.zoom,y:camera.y+(e.clientY-r.top)/camera.zoom};}
function zoom(factor,at){let r=svg.getBoundingClientRect(),a=at||{x:r.left+r.width/2,y:r.top+r.height/2},before=world({clientX:a.x,clientY:a.y});camera.zoom=Math.min(3,Math.max(.18,camera.zoom*factor));let after=world({clientX:a.x,clientY:a.y});camera.x+=before.x-after.x;camera.y+=before.y-after.y;applyCamera();}
function symbol(type,c={params:{}}){const m=meta(type);let s='';switch(type){case'resistor':s='<path d="M-40 0h20m40 0h20"/><rect x="-20" y="-8" width="40" height="16"/>';break;case'capacitor':s='<path d="M-40 0h34m12 0h34M-6-17v34M6-17v34"/>';break;case'inductor':s='<path d="M-40 0h16a6 10 0 0 1 12 0a6 10 0 0 1 12 0a6 10 0 0 1 12 0a6 10 0 0 1 12 0h16"/>';break;case'vdc':case'vac':s='<path d="M-40 0h18m44 0h18"/><circle r="22"/>'+(type==='vdc'?'<path d="M-15-4v8m-4-4h8M11 0h8"/>':'<path d="M-13 0q6-19 13 0t13 0"/>')+'<text x="-34" y="-9" style="font-size:10px">+</text><text x="27" y="-9" style="font-size:10px">−</text>';break;case'gnd':s='<path d="M0 0v13M-16 13h32M-10 19h20M-4 25h8"/>';break;case'schottky':case'zener':case'tunnel':case'diode':s='<path d="M-40 0h25m30 0h25M-15-14L15 0-15 14zM15-15v30"/>'+(type==='zener'?'<path d="M15-15h8M15 15h-8"/>':type==='schottky'?'<path d="M15-15h8v6M15 15h-8v-6"/>':type==='tunnel'?'<path d="M15-15h-7M15 15h-7"/>':'');break;case'opamp':s='<path d="M-40-20h15m-15 40h15M-25-37L35 0-25 37zM35 0h5"/><text x="-19" y="-15">+</text><text x="-19" y="25">−</text>'+(c.params.powered?'<path d="M0-60v38M0 60v-38"/><text x="7" y="-43" style="font-size:9px">V+</text><text x="7" y="49" style="font-size:9px">V−</text>':'');break;case'switch':s='<path d="M-40 0h15m50 0h15M-23 0L23 '+(c.params.closed?'0':'-17')+'"/><circle cx="-25" r="2"/><circle cx="25" r="2"/>';break;default:{const pins=m?.pins||[],height=Math.max(60,...pins.map(p=>Math.abs(p.y)*2+20));s=`<rect x="-28" y="${-height/2}" width="56" height="${height}" rx="2"/><text text-anchor="middle" x="0" y="4" style="font-size:${type.length>6?9:11}px">${esc(type==='input'?'IN '+(c.params.value??0):m?.shortLabel||type.toUpperCase())}</text>`;for(let p of pins){let target=p.x<0?-28:p.x>0?28:p.x;s+=`<path d="M${p.x} ${p.y}L${target} ${p.y}"/>`;if(pins.length>3)s+=`<text x="${p.x<0?-24:24}" y="${p.y-4}" text-anchor="${p.x<0?'start':'end'}" style="font-size:7px">${esc(p.id)}</text>`;}break;}}return `<g class="part-drawing">${s}</g>`;}
function valueLabel(c){if(c.type==='gnd')return '';if(c.type==='switch')return c.params.closed?'sepnuto':'rozepnuto';if(c.type==='opamp')return `A ${fmt(c.params.gain??1e5)}`;let unit=({resistor:'Ω',capacitor:'F',inductor:'H',vdc:'V',vac:'V',clock:'Hz'})[c.type]||'';let v=c.type==='clock'?c.params.frequency:c.params.value;return typeof v==='number'?fmt(v,unit):'';}
function renderLibrary(){const available=catalog.filter(allowed);const cats=['Vše',...new Set(available.map(c=>c.category||'Ostatní'))];$('#categories').innerHTML=cats.map(c=>`<button data-category="${esc(c)}" class="${c===category?'active':''}">${esc(c)}</button>`).join('');let q=$('#search').value.toLocaleLowerCase('cs');$('#parts').innerHTML=available.filter(c=>(category==='Vše'||c.category===category)&&`${c.label} ${c.type}`.toLocaleLowerCase('cs').includes(q)).map(c=>`<button class="part ${placing===c.type?'active':''}" data-part="${esc(c.type)}" title="${esc(c.description||c.label)}"><svg viewBox="-45 -30 90 60" aria-hidden="true">${symbol(c.type)}</svg><span>${esc(c.label)}</span></button>`).join('');$('#examples').innerHTML=examples.filter(e=>e.mode===workspaceMode).map(e=>`<button class="example" data-example="${esc(e.id)}">${esc(e.title)}<small>${esc(e.description||'')}</small></button>`).join('');}
function voltageAt(p){let d=displayed(),n=d?.nodeMap?.[key(p)];return n!==undefined?d.voltages?.[n]:undefined;}
function voltageColor(v){if(!Number.isFinite(v))return '#597387';if(Math.abs(v)<1e-8)return '#6f8290';let alpha=Math.min(1,Math.abs(v)/5),base=v>0?[28,128,110]:[183,69,84];return `rgb(${base.map((x,i)=>Math.round(115+(x-115)*alpha)).join(',')})`;}
function wireCurrents(){let map=new Map(),d=displayed();if(!d?.currents)return map;const links=new Map();for(const w of project.wires)for(const end of ['a','b']){let k=key(w[end]);if(!links.has(k))links.set(k,[]);links.get(k).push({w,end});}const terminals=new Set(project.components.flatMap(c=>localPins(c).map(key)));for(const c of project.components){const pins=localPins(c),i=d.currents[c.id];if(pins.length!==2||!Number.isFinite(i)||Math.abs(i)<1e-12)continue;for(let side=0;side<2;side++){let pos=key(pins[side]),seen=new Set(),outward=side===0?-i:i;while(true){let candidates=(links.get(pos)||[]).filter(x=>!seen.has(x.w.id));if(candidates.length!==1)break;let {w,end}=candidates[0];seen.add(w.id);map.set(w.id,end==='a'?outward:-outward);pos=key(w[end==='a'?'b':'a']);if(terminals.has(pos)||seen.size>project.wires.length)break;}}}return map;}
function wirePath(w){if(w.a.y!==w.b.y)return `M${w.a.x} ${w.a.y}L${w.b.x} ${w.b.y}`;let lo=Math.min(w.a.x,w.b.x),hi=Math.max(w.a.x,w.b.x),y=w.a.y;let xs=project.wires.filter(v=>v.a.x===v.b.x&&v.a.x>lo+7&&v.a.x<hi-7&&y>Math.min(v.a.y,v.b.y)&&y<Math.max(v.a.y,v.b.y)).map(v=>v.a.x);xs=[...new Set(xs)].filter(x=>!project.wires.some(v=>[v.a,v.b].some(p=>p.x===x&&p.y===y))&&!project.components.some(c=>localPins(c).some(p=>p.x===x&&p.y===y))&&!project.probes.some(p=>p.x===x&&p.y===y)).sort((a,b)=>a-b);let d=`M${lo} ${y}`;for(let x of xs)d+=`L${x-6} ${y}a6 6 0 0 1 12 0`;return d+`L${hi} ${y}`;}
function renderScene(){let out='',flow=wireCurrents();for(let w of project.wires){let d=wirePath(w);out+=`<g data-wire="${esc(w.id)}"><path class="wire-hit" d="${d}"/><path class="wire ${selected?.kind==='wire'&&selected.id===w.id?'selected':''}" style="stroke:${voltageColor(voltageAt(w.a))}" d="${d}"/>${flow.has(w.id)?`<path class="wire-flow" style="animation-delay:-${(performance.now()/1000%0.9).toFixed(3)}s;animation-direction:${(flow.get(w.id)*(w.a.y===w.b.y&&w.a.x>w.b.x?-1:1))<0?'reverse':'normal'}" d="${d}"/>`: ''}</g>`;}
let counts=new Map();for(let w of project.wires)for(let p of [w.a,w.b])counts.set(key(p),(counts.get(key(p))||0)+1);for(let c of project.components)for(let p of localPins(c))counts.set(key(p),(counts.get(key(p))||0)+1);for(let [k,n]of counts)if(n>=3){let [x,y]=k.split(',');out+=`<circle class="junction" cx="${x}" cy="${y}" r="3"/>`;}
for(let c of project.components){let isSelected=selected?.kind==='component'&&selected.id===c.id, h=Math.max(43,...(meta(c.type)?.pins||[]).filter(p=>c.type!=='opamp'||c.params?.powered||!['vcc','vee'].includes(p.id)).map(p=>Math.abs(p.y)+15)),vertical=Math.abs((c.rotation||0)%180)===90,lx=vertical?55:c.type==='gnd'?24:0,ly=vertical?-15:c.type==='gnd'?20:-h-7,vy=vertical?5:h+13,anchor=vertical||c.type==='gnd'?'start':'middle';out+=`<g class="component ${isSelected?'selected':''} ${faultIds.includes(c.id)?'fault':''}" data-component="${esc(c.id)}" transform="translate(${c.x} ${c.y})"><g transform="rotate(${c.rotation||0})"><rect class="selection-box" x="-47" y="${-h}" width="94" height="${h*2}" rx="3"/>${symbol(c.type,c)}</g><text class="component-label" x="${lx}" y="${ly}" text-anchor="${anchor}">${esc(c.params.label||c.id)}</text><text class="component-value" x="${lx}" y="${vy}" text-anchor="${anchor}">${esc(valueLabel(c))}</text>`;let current=displayed()?.currents?.[c.id];if(Number.isFinite(current)&&Math.abs(current)>1e-12&&c.type!=='gnd')out+=`<path class="current-indicator" transform="rotate(${c.rotation||0})" style="animation-direction:${current<0?'reverse':'normal'}" d="M-21 26h42"/><text class="component-value" x="${lx}" y="${vy+13}" text-anchor="${anchor}" fill="#b77922">${esc(fmt(current,'A'))}</text>`;out+='</g>';for(let p of localPins(c))out+=`<circle class="pin" data-pin="${esc(c.id)}:${esc(p.id)}" data-x="${p.x}" data-y="${p.y}" cx="${p.x}" cy="${p.y}" r="3.3"><title>${esc(c.id)} · ${esc(p.id)}</title></circle>`;}
for(let p of project.probes){let v=voltageAt(p);out+=`<g class="probe ${selected?.kind==='probe'&&selected.id===p.id?'selected':''}" data-probe="${esc(p.id)}"><path d="M${p.x} ${p.y}v-19" stroke="${p.color}" stroke-width="1.6"/><circle cx="${p.x}" cy="${p.y}" r="5" fill="#fff" stroke="${p.color}" stroke-width="2"/><text x="${p.x+7}" y="${p.y-22}" fill="${p.color}">${esc(p.label)}${Number.isFinite(v)?' '+esc(fmt(v,workspaceMode==='analog'?'V':'')):''}</text></g>`;}
scene.innerHTML=out;$('#emptyHint').hidden=project.components.length>0;$('#circuitStats').textContent=`${project.components.length} součástek · ${project.wires.length} vodičů · ${project.probes.length} sond`;document.body.classList.toggle('sim-running',running);renderPreview();}
function renderPreview(){let out='';if(placing)out=`<g opacity=".5" transform="translate(${snap(mouse.x)} ${snap(mouse.y)})">${symbol(placing)}</g>`;if(wireStart){let x=snap(mouse.x),y=snap(mouse.y);out+=`<path d="M${wireStart.x} ${wireStart.y}L${x} ${wireStart.y}L${x} ${y}" stroke="#c28030" stroke-width="2" fill="none" stroke-dasharray="5 4"/><circle cx="${wireStart.x}" cy="${wireStart.y}" r="5" fill="#c28030"/>`;}preview.innerHTML=out;}
const paramNames={powered:'Vnější napájení V+ / V−',breakdown:'Průrazné napětí [V]',rz:'Dynamický odpor [Ω]',peakCurrent:'Špičkový proud [A]',peakVoltage:'Špičkové napětí [V]',valleyCurrent:'Údolní proud [A]',valleyVoltage:'Údolní napětí [V]',value:'Hodnota',frequency:'Frekvence [Hz]',offset:'Stejnosměrný posun [V]',phase:'Počáteční fáze [°]',gain:'Otevřené zesílení',rail:'Napájecí meze ± [V]',slew:'Slew rate [V/s]',gbw:'Součin zesílení a pásma [Hz]',closed:'Sepnuto',delay:'Zpoždění [s]',preset:'Předvolba',bits:'Počet bitů',initial:'Počáteční stav',pt:'Nastavený čas [s]',period:'Perioda [s]',duty:'Střída',threshold:'Práh [V]',n:'Emisní koeficient diody',waveform:'Průběh generátoru'};
function renderProperties(){let el=$('#properties'),sel=selected;if(sel?.kind==='component'){let c=project.components.find(c=>c.id===sel.id);if(!c)return;const m=meta(c.type),params={...(m?.defaults||{}),...c.params};el.innerHTML=`<p class="property-kind">${esc(m?.label||c.type)}</p><label class="field"><span>Označení</span><input data-param="label" value="${esc(c.params.label||c.id)}"></label>${Object.entries(params).filter(([k,v])=>k!=='label'&&(typeof v==='number'||typeof v==='boolean'||k==='waveform')).map(([k,v])=>`<label class="field"><span>${esc(k==='value'?({capacitor:'Kapacita [F]',inductor:'Indukčnost [H]',resistor:'Odpor [Ω]',vdc:'Napětí [V]',vac:'Amplituda [V]',input:'Logická hodnota 0 / 1'})[c.type]||paramNames[k]:paramNames[k]||k)}</span>${k==='waveform'?`<select data-param="waveform">${[['sine','Sinus'],['square','Obdélník'],['triangle','Trojúhelník']].map(([id,label])=>`<option value="${id}" ${v===id?'selected':''}>${label}</option>`).join('')}</select>`:typeof v==='boolean'?`<select data-param="${esc(k)}"><option value="true" ${v?'selected':''}>Ano</option><option value="false" ${!v?'selected':''}>Ne</option></select>`:`<input data-param="${esc(k)}" value="${esc(v)}" inputmode="decimal">`}</label>`).join('')}${['vdc','vac'].includes(c.type)?`<label class="field"><span>Živá změna napětí [V]</span><input id="liveVoltage" type="range" min="${c.type==='vdc'?-20:0}" max="20" step="0.05" value="${params.value}"><output id="liveValue">${esc(fmt(params.value,'V'))}</output></label>`:''}<div class="property-actions"><button id="duplicate">Duplikovat</button><button id="rotateSelected">Otočit 90°</button></div>${Number.isFinite(displayed()?.currents?.[c.id])?`<p class="subtle">Proud a → b: ${esc(fmt(displayed().currents[c.id],'A'))}</p>`:''}`;
}else if(sel?.kind==='probe'){let p=project.probes.find(p=>p.id===sel.id);el.innerHTML=`<p class="property-kind">Napěťová sonda</p><label class="field"><span>Označení</span><input id="probeLabel" value="${esc(p.label)}"></label><p class="subtle">Měření uzlu vůči zemi. Připojte alespoň jednu zem k obvodu.</p><button id="removeSelected" class="outline">Odstranit sondu</button>`;
}else if(sel?.kind==='wire'){el.innerHTML='<p class="property-kind">Vodič</p><p class="subtle">Křížení bez společného koncového bodu není elektrický spoj. Pro odbočku začněte nový vodič na stávajícím vodiči.</p><button id="removeSelected" class="outline">Odstranit vodič</button>';}else el.innerHTML='<p class="property-empty">Vyberte součástku pro nastavení hodnoty.<br><br>Hodnoty lze zadávat také jako <b>4.7k</b>, <b>100n</b> nebo <b>1e6</b>.</p>';
$('#probeList').innerHTML=project.probes.length?project.probes.map(p=>`<div class="probe-row"><i class="probe-dot" style="background:${p.color}"></i><span>${esc(p.label)}</span><b>${Number.isFinite(voltageAt(p))?esc(fmt(voltageAt(p),workspaceMode==='analog'?'V':'')):''}</b><button data-remove-probe="${esc(p.id)}" aria-label="Odstranit ${esc(p.label)}">×</button></div>`).join(''):'<p class="subtle">Zvolte Sondu a klikněte na vývod nebo vodič.</p>';
$('#simulationSummary').innerHTML=result?`<div>${tab==='bode'?'AC analýza':'Časová analýza'}</div><div>${tab==='bode'?`${result.frequency?.length||0} frekvencí`:`${result.time?.length||0} časových bodů`}</div><div>${tab==='bode'?'':`t = ${esc(fmt(playback,'s'))}`}</div>`:'Výpočet není spuštěn.';
}
function renderSettings(){let s=project.settings;if(workspaceMode!=='analog'){$('#instrumentSettings').innerHTML=`<label>Délka záznamu <input data-setting="duration" value="${s.duration??.05}" aria-label="Délka simulace"> s</label><label>Krok záznamu <input data-setting="step" value="${s.step??1e-4}" aria-label="Časový krok"> s</label><span>Dvojklik na vstup přepne 0 / 1.</span><button id="analyze">Přepočítat</button>`;$('#measurementInfo').textContent='Logické stavy 0 / 1 · X = neurčený stav · Z = odpojený výstup';return;}
let basic=tab==='bode'?`<label>Od <input data-setting="acStart" value="${s.acStart??10}" aria-label="Počáteční frekvence"> Hz</label><label>Do <input data-setting="acStop" value="${s.acStop??1e5}" aria-label="Koncová frekvence"> Hz</label><button id="analyze">Změřit přenos</button>`:tab==='scope'?`<label>Měření <select id="currentSelect"><option value="">Napětí sond</option>${project.components.filter(c=>c.type!=='gnd').map(c=>`<option value="${esc(c.id)}" ${s.currentId===c.id?'selected':''}>Proud ${esc(c.id)}</option>`).join('')}</select></label><label>Délka záznamu <input data-setting="duration" value="${s.duration??.01}" aria-label="Délka simulace"> s</label><button id="analyze">Přepočítat</button>`:'<span>Napětí a proudy po ustálení obvodu.</span><button id="analyze">Změřit hodnoty</button>';
$('#instrumentSettings').innerHTML=basic+`<details class="analysis-advanced"><summary>Nastavení výpočtu</summary><div><label>Výpočetní jádro <select id="engineSelect" aria-label="Výpočetní jádro"><option value="mna" ${s.engine!=='spice'?'selected':''}>Interaktivní model</option><option value="spice" ${s.engine==='spice'?'selected':''}>SPICE / ngspice</option></select></label>${tab==='scope'?`<label>Časový krok <input data-setting="step" value="${s.step??5e-6}" aria-label="Časový krok"> s</label><label>Spuštění na napětí <input id="triggerLevel" value="${s.triggerLevel??''}" placeholder="auto" aria-label="Úroveň triggeru"> V</label><p>Menší krok zpřesní výpočet. Rychlost přehrávání jej nemění.</p>`:tab==='bode'?`<label>Počet bodů <input data-setting="acPoints" value="${s.acPoints??180}" aria-label="Počet frekvencí"></label><p>Přenos vůči vstupnímu generátoru. Přerušovaná čára je fáze.</p>`:'<p>Kondenzátor je po ustálení rozpojený, cívka zkratovaná.</p>'}</div></details>`;
$('#measurementInfo').textContent=tab==='bode'?'Přenos: poměr výstupu ke vstupu · plná čára dB · přerušovaná fáze °':tab==='scope'?'Sondy měří vůči zemi · pozastavte a přečtěte hodnotu kurzorem nebo krokujte':'Stejnosměrné napětí vůči zemi · proud a → b';}

function render(){renderScene();renderProperties();renderSettings();renderChart();$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;$('#sheetTitle').textContent=project.title;$('#title').value=project.title;}
function setTool(t){tool=t;placing=null;wireStart=null;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#toolHint').textContent=({select:'Tažením přesuňte. Dvojklik přepne vstup / spínač. Pravé tlačítko otočí.',wire:'Klikněte na začátek a konec vodiče. Esc ukončí spojování.',probe:'Klikněte na vodič nebo vývod pro měření napětí vůči zemi.'})[t];svg.style.cursor=t==='select'?'default':'crosshair';renderLibrary();renderPreview();}
function choosePart(type){setTool('select');placing=type;$('#toolHint').textContent=`${meta(type)?.label||type}: kliknutím umístíte do schématu. Esc ukončí vkládání.`;svg.style.cursor='crosshair';renderLibrary();}
function connect(a,b){if(a.x===b.x&&a.y===b.y)return;let corner={x:b.x,y:a.y};let segments=[];if(a.x!==corner.x||a.y!==corner.y)segments.push({id:uid('w'),a:clone(a),b:corner});if(corner.x!==b.x||corner.y!==b.y)segments.push({id:uid('w'),a:corner,b:clone(b)});for(let w of segments){if(!project.wires.some(z=>(key(z.a)===key(w.a)&&key(z.b)===key(w.b))||(key(z.a)===key(w.b)&&key(z.b)===key(w.a))))project.wires.push(w);}}
function splitAt(p){let next=[];for(let w of project.wires){let on=(w.a.x===w.b.x&&p.x===w.a.x&&p.y>Math.min(w.a.y,w.b.y)&&p.y<Math.max(w.a.y,w.b.y))||(w.a.y===w.b.y&&p.y===w.a.y&&p.x>Math.min(w.a.x,w.b.x)&&p.x<Math.max(w.a.x,w.b.x));if(on){next.push({...w,b:clone(p)},{id:uid('w'),a:clone(p),b:w.b});}else next.push(w);}project.wires=next;}
function pinPoint(e,p){let pin=e.target.closest('[data-pin]');if(pin)return {x:Number(pin.dataset.x),y:Number(pin.dataset.y)};return {x:snap(p.x),y:snap(p.y)};}
function addProbe(p){snapshot();splitAt(p);let n=project.probes.length+1;project.probes.push({id:uid('p'),label:'U'+n,x:p.x,y:p.y,color:colors[(n-1)%colors.length]});selected={kind:'probe',id:project.probes.at(-1).id};changed();}
function deleteSelected(){if(!selected)return;snapshot();if(selected.kind==='component')project.components=project.components.filter(c=>c.id!==selected.id);if(selected.kind==='wire')project.wires=project.wires.filter(c=>c.id!==selected.id);if(selected.kind==='probe')project.probes=project.probes.filter(c=>c.id!==selected.id);selected=null;changed();}
function orthogonalize(){let next=[];for(let w of project.wires){if(w.a.x!==w.b.x&&w.a.y!==w.b.y){let corner={x:w.b.x,y:w.a.y};next.push({...w,b:corner},{id:uid('w'),a:clone(corner),b:clone(w.b)});}else next.push(w);}project.wires=next;}
function rotateSelected(){if(selected?.kind!=='component')return;let c=project.components.find(c=>c.id===selected.id);snapshot();let old=localPins(c);c.rotation=((c.rotation||0)+90)%360;let pins=localPins(c);for(let w of project.wires)for(let end of ['a','b']){let i=old.findIndex(p=>key(p)===key(w[end]));if(i>=0)w[end]={x:pins[i].x,y:pins[i].y};}for(let pr of project.probes){let i=old.findIndex(p=>key(p)===key(pr));if(i>=0)Object.assign(pr,{x:pins[i].x,y:pins[i].y});}orthogonalize();changed();}

function duplicate(){if(selected?.kind!=='component')return;let c=clone(project.components.find(c=>c.id===selected.id));snapshot();c.id=nextId(c.type);c.x+=40;c.y+=60;delete c.params.label;project.components.push(c);selected={kind:'component',id:c.id};changed();}
function nextId(type){let prefix=({resistor:'R',capacitor:'C',inductor:'L',vdc:'V',vac:'V',gnd:'GND',diode:'D',opamp:'U',switch:'S'})[type]||type.toUpperCase();let n=1;while(project.components.some(c=>c.id===prefix+n))n++;return prefix+n;}
svg.addEventListener('pointerdown',e=>{if(e.button===2)return;let p=world(e);mouse=p;if(e.button===1||e.altKey){svg.setPointerCapture(e.pointerId);drag={kind:'pan',start:{x:e.clientX,y:e.clientY},camera:{...camera}};e.preventDefault();return;}if(placing){snapshot();let c={id:nextId(placing),type:placing,x:snap(p.x),y:snap(p.y),rotation:0,params:clone(meta(placing)?.defaults||{})};project.components.push(c);selected={kind:'component',id:c.id};placing=null;svg.style.cursor='default';changed();renderLibrary();return;}if(tool==='probe'){addProbe(pinPoint(e,p));return;}if(tool==='wire'||e.target.closest('[data-pin]')){let point=pinPoint(e,p);if(!wireStart){wireStart=point;renderPreview();}else{snapshot();splitAt(wireStart);splitAt(point);connect(wireStart,point);wireStart=e.target.closest('[data-pin]')?null:point;changed();}return;}let comp=e.target.closest('[data-component]'),probe=e.target.closest('[data-probe]'),wire=e.target.closest('[data-wire]');if(comp){selected={kind:'component',id:comp.dataset.component};let c=project.components.find(c=>c.id===selected.id);drag={kind:'component',id:c.id,start:p,x:c.x,y:c.y,original:clone(project),moved:false,pins:localPins(c)};}else if(probe){selected={kind:'probe',id:probe.dataset.probe};let pr=project.probes.find(q=>q.id===selected.id);drag={kind:'probe',id:pr.id,start:p,x:pr.x,y:pr.y,original:clone(project),moved:false};}else if(wire){selected={kind:'wire',id:wire.dataset.wire};}else selected=null;scene.querySelectorAll('.component.selected').forEach(el=>el.classList.remove('selected'));if(comp)comp.classList.add('selected');renderProperties();});
svg.addEventListener('pointermove',e=>{let p=world(e);mouse=p;$('#coordinates').textContent=`${snap(p.x)}, ${snap(p.y)}`;if(drag?.kind==='pan'){camera.x=drag.camera.x-(e.clientX-drag.start.x)/camera.zoom;camera.y=drag.camera.y-(e.clientY-drag.start.y)/camera.zoom;applyCamera();return;}if(drag?.kind==='component'){let c=project.components.find(c=>c.id===drag.id),dx=snap(p.x-drag.start.x),dy=snap(p.y-drag.start.y);if(!dx&&!dy&&!drag.moved)return;svg.setPointerCapture(e.pointerId);c.x=drag.x+dx;c.y=drag.y+dy;drag.moved=true;let original=drag.original;project.wires=clone(original.wires);for(let w of project.wires)for(let end of ['a','b'])if(drag.pins.some(pin=>key(pin)===key(w[end]))){w[end].x+=dx;w[end].y+=dy;}project.probes=clone(original.probes);for(let pr of project.probes)if(drag.pins.some(pin=>key(pin)===key(pr))){pr.x+=dx;pr.y+=dy;}renderScene();return;}if(drag?.kind==='probe'){let pr=project.probes.find(q=>q.id===drag.id);pr.x=drag.x+snap(p.x-drag.start.x);pr.y=drag.y+snap(p.y-drag.start.y);drag.moved=true;renderScene();return;}renderPreview();});
function finishDrag(){if(drag?.moved){orthogonalize();history.push(JSON.stringify(drag.original));future=[];changed();}drag=null;}
svg.addEventListener('pointerup',finishDrag);svg.addEventListener('pointercancel',finishDrag);svg.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-e.deltaY*.0015),{x:e.clientX,y:e.clientY});},{passive:false});
svg.addEventListener('dblclick',e=>{let item=e.target.closest('[data-component]');if(!item)return;let c=project.components.find(c=>c.id===item.dataset.component);if(c.type==='switch'||c.type==='input'){snapshot();if(c.type==='switch')c.params.closed=!c.params.closed;else c.params.value=c.params.value?0:1;changed();if(project.probes.length)simulate();}});
function validateProject(p){if(!p||p.version!==1||!Array.isArray(p.components)||!Array.isArray(p.wires)||!Array.isArray(p.probes))throw Error('Soubor nemá podporovaný formát projektu SHiELDiO Sim.');if(p.components.length>250||p.wires.length>1500||p.probes.length>32)throw Error('Projekt překračuje limit bety (250 součástek, 1500 vodičů, 32 sond).');let ids=new Set();for(let c of p.components){if(!meta(c.type))throw Error('Nepodporovaná součástka: '+c.type);if(typeof c.id!=='string'||ids.has(c.id))throw Error('Součástky musí mít jedinečné označení.');ids.add(c.id);if(!Number.isFinite(c.x)||!Number.isFinite(c.y)||Math.abs(c.x)>100000||Math.abs(c.y)>100000||![0,90,180,270].includes(c.rotation||0))throw Error('Neplatná pozice součástky.');c.params=c.params||{};for(let [k,v]of Object.entries(c.params))if(typeof v==='number'&&!Number.isFinite(v))throw Error('Neplatná hodnota součástky.');}for(let w of p.wires)for(let end of ['a','b'])if(!Number.isFinite(w[end]?.x)||!Number.isFinite(w[end]?.y))throw Error('Neplatný vodič.');for(let [i,pr]of p.probes.entries()){if(!Number.isFinite(pr.x)||!Number.isFinite(pr.y))throw Error('Neplatná sonda.');pr.label=String(pr.label||'U'+(i+1)).slice(0,40);pr.color=/^#[a-f\d]{6}$/i.test(pr.color)?pr.color:colors[i%colors.length];}let pm=modeOf(p);if(p.components.some(c=>pm==='analog'?!!meta(c.type)?.modes:!meta(c.type)?.modes?.includes(pm)))throw Error('Projekt míchá pracovní režimy. Analog, číslicová technika a FBD musí být v samostatných projektech.');if(!['analog','digital','fbd'].includes(pm))throw Error('Neznámý pracovní režim.');p.mode=pm;p.title=String(p.title||'Obvod').slice(0,100);p.settings={...empty().settings,...p.settings};return p;}
function loadProject(p){snapshot();project=validateProject(clone(p));workspaceMode=modeOf(project);project.mode=workspaceMode;category='Vše';applyMode();selected=null;setTool('select');changed();setTimeout(fit,30);}
function download(name,data,mime){let url=URL.createObjectURL(new Blob([data],{type:mime}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function filename(ext){return (project.title||'obvod').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').slice(0,70)+'.'+ext;}
function dialog(title,html){$('#closeDialog').hidden=false;$('#dialog').oncancel=null;$('#dialogTitle').textContent=title;$('#dialogContent').innerHTML=html;$('#dialog').showModal();}
async function share(){try{let data=new TextEncoder().encode(JSON.stringify(project)),encoded;if('CompressionStream'in window){let cs=new CompressionStream('deflate');let out=new Response(new Blob([data]).stream().pipeThrough(cs));data=new Uint8Array(await out.arrayBuffer());encoded='z';}else encoded='j';let binary='';for(let b of data)binary+=String.fromCharCode(b);let url=location.origin+location.pathname+'#'+encoded+btoa(binary).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');if(url.length>50000){toast('Projekt je pro odkaz příliš velký. Použijte export souboru.',true);return;}dialog('Sdílet obvod',`<p>Odkaz obsahuje kopii projektu včetně nastavení a sond. Příjemce jej může otevřít a upravit. Pozdější úpravy tuto kopii nemění.</p><input id="shareUrl" readonly value="${esc(url)}"><div class="dialog-actions"><button id="copyLink" class="primary">Kopírovat odkaz</button></div>`);$('#copyLink').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Odkaz zkopírován.');}catch{$('#shareUrl').select();document.execCommand('copy');toast('Odkaz je připravený ke kopírování.');}};}catch(e){toast('Sdílení selhalo: '+e.message,true);}}
async function readHash(){let hash=location.hash.slice(1);if(!hash||!['z','j'].includes(hash[0]))return false;if(hash.length>100000)throw Error('Odkaz s projektem je příliš velký.');let b64=hash.slice(1).replace(/-/g,'+').replace(/_/g,'/'),binary=atob(b64),data=Uint8Array.from(binary,c=>c.charCodeAt(0));if(hash[0]==='z'){if(!('DecompressionStream'in window))throw Error('Tento prohlížeč neumí otevřít komprimovaný odkaz. Použijte import souboru.');let ds=new DecompressionStream('deflate');data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(ds)).arrayBuffer());}if(data.length>3000000)throw Error('Projekt v odkazu je příliš velký.');project=validateProject(JSON.parse(new TextDecoder().decode(data)));return true;}
function exportSvg(){let b=bounds(),chart=$('#chart svg'),extra=chart?240:0;let styles=`text{font-family:ui-monospace,Consolas,monospace}.part-drawing{fill:none;stroke:#294359;stroke-width:1.8;stroke-linejoin:round;stroke-linecap:round}.part-drawing text{stroke:none;fill:#294359;font-size:13px}.component-label{font-size:12px;fill:#314b60}.component-value{font-size:10px;fill:#6c7d8b}.selection-box{fill:none;stroke:none}.wire{stroke:#597387;stroke-width:1.8;fill:none}.wire-hit,.pin,.current-indicator,.wire-flow{display:none}.component-label,.component-value{paint-order:stroke;stroke:white;stroke-width:4px}.junction{fill:#597387}.probe text{font-size:11px;stroke:none}.plot-grid{stroke:#dce3ea;stroke-width:1}`;let sc=scene.cloneNode(true);sc.querySelectorAll('.selected').forEach(el=>el.classList.remove('selected'));let width=Math.max(900,b.w+80),height=b.h+110+extra;let chartStr='';if(chart){let c=chart.cloneNode(true);c.setAttribute('x','35');c.setAttribute('y',String(b.h+95));c.setAttribute('width',String(width-70));c.setAttribute('height','210');c.querySelectorAll('text').forEach(t=>{t.setAttribute('fill','#405b72');t.setAttribute('font-size','9');});const shown=(result?.traces||[]).filter(t=>tab==='bode'||(project.settings.currentId?t.id==='I:'+project.settings.currentId:t.unit!=='A'));let legendX=0;const legend=shown.map((t,i)=>{const x=legendX;legendX+=Math.max(110,t.label.length*7+25);return `<text x="${35+x}" y="${b.h+86}" font-size="10" fill="${project.probes.find(p=>p.id===t.id)?.color||colors[i%colors.length]}">${esc(t.label)}${t.unit?' ['+esc(t.unit)+']':''}</text>`;}).join('');chartStr=legend+c.outerHTML;}
return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><style>${styles}</style><rect width="100%" height="100%" fill="white"/><text x="35" y="35" font-size="19" fill="#233549">${esc(project.title)}</text><text x="35" y="56" font-size="10" fill="#637488">SHiELDiO Sim · ${esc(new Date().toLocaleDateString('cs-CZ'))} · ${tab==='bode'?'AC přenos a fáze':tab==='dc'?'DC napětí a proudy':'časový průběh'}${tab==='scope'?' · t = '+esc(fmt(instantResult?.time??playback,'s')):''} · ${project.settings.engine==='spice'?'ngspice':'interaktivní model'}</text><g transform="translate(${35-b.x} ${80-b.y})">${sc.innerHTML}</g>${chartStr}<text x="35" y="${height-16}" font-size="9" fill="#637488">Modelová simulace · ${esc(fmt(project.settings.step,'s'))} časový krok · ${esc(fmt(project.settings.duration,'s'))} délka · napětí vůči zemi</text></svg>`;}
async function pngExport(){let text=exportSvg(),blob=new Blob([text],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob);try{let image=new Image();image.src=url;await image.decode();let canvas=document.createElement('canvas');let scale=Math.min(2,6000/Math.max(image.width,image.height));canvas.width=image.width*scale;canvas.height=image.height*scale;let ctx=canvas.getContext('2d');ctx.scale(scale,scale);ctx.drawImage(image,0,0);let out=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!out)throw Error('Nepodařilo se vykreslit obrázek.');download(filename('png'),out,'image/png');}finally{URL.revokeObjectURL(url);}}
function exportCsv(){if(!result&&tab!=='dc'){toast('Nejdřív spusťte simulaci.',true);return;}let lines=[];if(tab==='bode'){lines.push(['f_Hz',...result.traces.flatMap(t=>[t.label+'_dB',t.label+'_deg'])].join(';'));for(let i=0;i<result.frequency.length;i++)lines.push([result.frequency[i],...result.traces.flatMap(t=>[t.magnitude[i],t.phase[i]])].join(';'));}else if(tab==='dc'){if(!dcResult)return toast('Nejdřív vypočítejte napětí a proudy.',true);lines.push('typ;oznaceni;hodnota;jednotka');for(let [id,v]of Object.entries(dcResult.voltages||{}))lines.push(`napeti;${id};${v};V`);for(let [id,v]of Object.entries(dcResult.currents||{}))lines.push(`proud;${id};${v};A`);}else{lines.push(['t_s',...result.traces.map(t=>t.label+'_'+t.unit)].join(';'));for(let i=0;i<result.time.length;i++)lines.push([result.time[i],...result.traces.map(t=>t.values[i])].join(';'));}download(filename('csv'),lines.join('\n'),'text/csv;charset=utf-8');}
function stop(){running=false;cancelAnimationFrame(raf);document.body.classList.remove('sim-running');$('#run').textContent='▶ Spustit';}
function showSample(){if(!result?.time)return;let i=Math.max(0,Math.min(result.time.length-1,Math.round(playback/(result.step||project.settings.step))));let voltages={'0':0},currents={};for(let [node,vals]of Object.entries(result.nodeTraces||{}))voltages[node]=vals[i];for(let tr of result.traces||[])if(tr.id.startsWith('I:'))currents[tr.id.slice(2)]=tr.values[i];instantResult={voltages,currents,nodeMap:result.nodeMap,time:result.time[i]};renderScene();if(!$('#properties').contains(document.activeElement))renderProperties();renderChart();$('#cursorReadout').textContent='t = '+fmt(result.time[i],'s')+' · '+(project.settings.currentId?'I = '+fmt(currents[project.settings.currentId],'A'):project.probes.map(p=>p.label+' '+fmt(voltages[result.nodeMap?.[key(p)]],workspaceMode==='analog'?'V':'')).join(' · '));}
function startPlayback(){if(!result?.time?.length)return;running=true;lastFrame=performance.now();let lastPaint=0;$('#run').textContent='Ⅱ Pozastavit';document.body.classList.add('sim-running');function frame(now){if(!running)return;let duration=result.time.at(-1)||.01;playback=(playback+(now-lastFrame)/1000*duration/4*playSpeed)%duration;lastFrame=now;if(now-lastPaint>65){lastPaint=now;showSample();}raf=requestAnimationFrame(frame);}raf=requestAnimationFrame(frame);}
async function simulate(){if(busy){cancelSolver();return;}if(running){stop();return;}if(tab==='scope'&&result?.time?.length&&!dirty){startPlayback();return;}if(!project.components.length){toast('Nejdřív vložte součástky nebo otevřete vzorový obvod.',true);return;}busy=true;$('#run').textContent='■ Zastavit výpočet';$('#run').disabled=false;$('#toolHint').textContent='Probíhá výpočet obvodu…';await new Promise(r=>setTimeout(r,20));try{let settings=project.settings;if(tab==='scope'&&(!(settings.duration>0)||!(settings.step>0)||settings.step>settings.duration||settings.duration/settings.step>100000))throw Error('Zvolte kladnou délku a krok, nejvýše 100 000 časových bodů.');if(tab==='bode'&&(!(settings.acStart>0)||!(settings.acStop>settings.acStart)||settings.acStop>1e10))throw Error('AC rozsah musí být kladný a vzestupný, nejvýše do 10 GHz.');let bundle=await runSolver({mode:'bundle',project,options:{analysis:tab,settings}});dcResult=bundle.dc;result=bundle.analysis;instantResult=null;playback=0;dirty=false;render();$('#toolHint').textContent=tab==='bode'?'AC analýza dokončena. Přerušovaná křivka zobrazuje fázi.':tab==='dc'?'DC napětí a proudy vypočten.':'Výpočet dokončen. Přehrává se vypočtený časový průběh.';if(tab==='scope')startPlayback();if(!project.probes.length&&tab!=='dc')toast('Výpočet dokončen. Přidejte sondu na měřený výstup.');if(result?.warnings?.length)toast(result.warnings.join(' '));}catch(e){stop();result=null;dcResult=null;instantResult=null;faultIds=project.components.filter(c=>(e.message||'').includes(c.id)).map(c=>c.id);render();$('#toolHint').textContent='Výpočet se nezdařil. Zkontrolujte zapojení.';toast(e.message||'Výpočet se nezdařil.',true);}finally{busy=false;$('#run').disabled=false;if(!running)$('#run').textContent='▶ Spustit';}}
function statistics(values,time){let nums=values.filter(Number.isFinite);if(!nums.length)return {};let max=nums.reduce((a,b)=>Math.max(a,b),-Infinity),min=nums.reduce((a,b)=>Math.min(a,b),Infinity),mean=nums.reduce((a,b)=>a+b,0)/nums.length,rms=Math.sqrt(nums.reduce((a,b)=>a+b*b,0)/nums.length),crossings=[];for(let i=Math.floor(values.length*.1)+1;i<values.length;i++){if(values[i-1]<mean&&values[i]>=mean&&values[i]>values[i-1])crossings.push(time[i-1]+(mean-values[i-1])/(values[i]-values[i-1])*(time[i]-time[i-1]));}let frequency=crossings.length>=2?(crossings.length-1)/(crossings.at(-1)-crossings[0]):null;return {max,min,mean,rms,pp:max-min,frequency,crossings};}
function renderChart(){let el=$('#chart'),read=$('#readings');if(tab==='dc'){read.innerHTML='';if(!dcResult){el.innerHTML='<p>Spusťte výpočet napětí a proudů pro zobrazení napětí a proudů.</p>';return;}let rows=[...project.probes.map(p=>[p.label,fmt(voltageAt(p),'V')]),...Object.entries(dcResult.currents||{}).map(([id,v])=>[id,fmt(v,'A')])];el.innerHTML=`<div style="height:100%;overflow:auto"><table class="dc-table"><thead><tr><th>Prvek / sonda</th><th>Hodnota</th></tr></thead><tbody>${rows.map(([id,v])=>`<tr><td>${esc(id)}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div>`;return;}
if(!result||!(tab==='bode'?result.frequency:result.time)){el.innerHTML='<p>Připojte sondu na měřený uzel a spusťte simulaci.<br>Výsledky se zobrazí zde.</p>';read.innerHTML='';return;}let traces=(result.traces||[]).filter(t=>tab==='bode'||(project.settings.currentId?t.id==='I:'+project.settings.currentId:t.unit!=='A')),W=800,H=180,L=48,R=tab==='bode'?51:17,T=12,B=27,PW=W-L-R,PH=H-T-B;let out='';let xValues=tab==='bode'?result.frequency:result.time;
if(!xValues?.length)return;if(tab==='scope'&&Number.isFinite(project.settings.triggerLevel)&&traces.length){let vals=traces[0].values,level=project.settings.triggerLevel,trigger=-1;for(let i=1;i<vals.length;i++)if(vals[i-1]<level&&vals[i]>=level){trigger=i;break;}if(trigger>0&&trigger<vals.length-10){xValues=xValues.slice(trigger);traces=traces.map(t=>({...t,values:t.values.slice(trigger)}));}}let minX=xValues[0],maxX=xValues.at(-1),minY,maxY;if(tab==='scope'&&result.time?.length){const width=(result.time.at(-1)||.01)/2,end=Math.min(result.time.at(-1),Math.max(playback,project.settings.step)),start=Math.max(0,end-width);let first=xValues.findIndex(x=>x>=start),last=xValues.findIndex(x=>x>end);if(last<0)last=xValues.length;first=Math.max(0,first);xValues=xValues.slice(first,Math.max(first+1,last));traces=traces.map(t=>({...t,values:t.values.slice(first,Math.max(first+1,last))}));minX=end-width;maxX=end;}let finite=(result.traces||[]).filter(t=>tab==='bode'||(project.settings.currentId?t.id==='I:'+project.settings.currentId:t.unit!=='A')).flatMap(t=>(tab==='bode'?t.magnitude:t.values).filter(Number.isFinite));if(!finite.length){el.innerHTML='<p>Žádná měřicí data. Připojte sondu k platnému uzlu.</p>';read.innerHTML='';return;}
minY=finite.reduce((a,b)=>Math.min(a,b),Infinity);maxY=finite.reduce((a,b)=>Math.max(a,b),-Infinity);let pad=(maxY-minY)*.12||Math.max(1,Math.abs(maxY)*.2);minY-=pad;maxY+=pad;const sx=x=>L+(tab==='bode'?(Math.log10(x)-Math.log10(minX))/(Math.log10(maxX)-Math.log10(minX)):(x-minX)/(maxX-minX||1))*PW;const sy=y=>T+(maxY-y)/(maxY-minY)*PH;
for(let i=0;i<=5;i++){let y=T+i*PH/5,v=maxY-i*(maxY-minY)/5;out+=`<line class="plot-grid" x1="${L}" y1="${y}" x2="${W-R}" y2="${y}"/><text x="${L-7}" y="${y+3}" text-anchor="end">${esc(tab==='bode'?Number(v.toPrecision(3)):fmt(v))}</text>`;}
for(let i=0;i<=8;i++){let x=L+i*PW/8,v=tab==='bode'?10**(Math.log10(minX)+i*(Math.log10(maxX)-Math.log10(minX))/8):minX+i*(maxX-minX)/8;out+=`<line class="plot-grid" x1="${x}" y1="${T}" x2="${x}" y2="${H-B}"/><text x="${x}" y="${H-9}" text-anchor="middle">${esc(fmt(v,tab==='bode'?'Hz':'s',2))}</text>`;}
out+=`<text x="${L}" y="9">${tab==='bode'?'dB':project.settings.currentId?'A':'V / logika'}</text>`;if(tab==='bode')for(let i=0;i<=4;i++)out+=`<text x="${W-2}" y="${T+i*PH/4+3}" text-anchor="end">${180-i*90}°</text>`;
traces.forEach((tr,i)=>{let color=project.probes.find(p=>p.id===tr.id)?.color||colors[i%colors.length],vals=tab==='bode'?tr.magnitude:tr.values;let d='',stride=Math.max(1,Math.floor(vals.length/1600));for(let j=0;j<vals.length;j+=stride){if(!Number.isFinite(vals[j])){d+=' ';continue;}d+=(j===0||!Number.isFinite(vals[Math.max(0,j-stride)])?'M':'L')+sx(xValues[j]).toFixed(2)+' '+sy(vals[j]).toFixed(2);}out+=`<path d="${d}" fill="none" stroke="${color}" stroke-width="1.6" vector-effect="non-scaling-stroke"/>`;if(tab==='bode'){let dp='';for(let j=0;j<tr.phase.length;j++)if(Number.isFinite(tr.phase[j]))dp+=(j?'L':'M')+sx(xValues[j]).toFixed(2)+' '+(T+(180-Math.max(-180,Math.min(180,tr.phase[j])))/360*PH).toFixed(2);out+=`<path d="${dp}" fill="none" stroke="${color}" stroke-width="1.2" stroke-dasharray="5 4" vector-effect="non-scaling-stroke"/>`;}});
if(tab==='scope'){let xp=sx(playback);out+=`<line id="playhead" x1="${xp}" x2="${xp}" y1="${T}" y2="${H-B}" stroke="#bfd5e4" stroke-width="1" opacity=".5"/>`;}
out+=`<line id="cursorLine" x1="0" x2="0" y1="${T}" y2="${H-B}" stroke="#c7dfef" stroke-width=".8" visibility="hidden"/>`;el.innerHTML=`<svg data-minx="${minX}" data-maxx="${maxX}" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-label="${tab==='bode'?'Frekvenční charakteristika':'Časové průběhy'}">${out}</svg>`;
read.innerHTML=traces.map((tr,i)=>{let color=project.probes.find(p=>p.id===tr.id)?.color||colors[i%colors.length];if(tab==='bode'){let middle=Math.floor(tr.magnitude.length/2);return `<div class="reading"><strong style="color:${color}">${esc(tr.label)}</strong><p>${esc(fmt(xValues[middle],'Hz'))}</p><p>${Number(tr.magnitude[middle]).toFixed(2)} dB</p><p>${Number(tr.phase[middle]).toFixed(1)}°</p></div>`;}let full=result.traces.find(t=>t.id===tr.id)||tr;let s=statistics(full.values,result.time),phase='';if(i>0&&s.frequency){let ref=statistics(result.traces.find(t=>t.id===traces[0].id).values,result.time);if(ref.crossings?.length&&s.crossings?.length){let period=1/s.frequency,dt=s.crossings[0]-ref.crossings[0];let deg=((-dt/period*360+180)%360+360)%360-180;phase=`<p>φ ≈ ${deg.toFixed(1)}°</p>`;}}return `<div class="reading"><strong style="color:${color}">${esc(tr.label)}</strong><p>RMS ${esc(fmt(s.rms,tr.unit==='logic'?'':tr.unit||'V'))}</p><p>p-p ${esc(fmt(s.pp,tr.unit==='logic'?'':tr.unit||'V'))}</p>${s.frequency?`<p>f ${esc(fmt(s.frequency,'Hz'))}</p>`:''}${phase}</div>`;}).join('');
el.onpointermove=e=>{let r=el.getBoundingClientRect(),px=(e.clientX-r.left)/r.width*W;if(px<L||px>W-R)return;let fraction=(px-L)/PW,x=tab==='bode'?10**(Math.log10(minX)+fraction*(Math.log10(maxX)-Math.log10(minX))):minX+fraction*(maxX-minX),idx=xValues.findIndex(v=>v>=x);idx=Math.max(0,idx);let line=$('#cursorLine');if(line){line.setAttribute('x1',px);line.setAttribute('x2',px);line.setAttribute('visibility','visible');}$('#cursorReadout').textContent=fmt(x,tab==='bode'?'Hz':'s')+' · '+traces.map(tr=>tr.label+' '+(tab==='bode'?Number(tr.magnitude[idx]).toFixed(1)+' dB / '+Number(tr.phase[idx]).toFixed(1)+'°':fmt(tr.values[idx],tr.unit==='logic'?'':tr.unit||'V'))).join(' · ');};el.onpointerleave=()=>{$('#cursorLine')?.setAttribute('visibility','hidden');};}
function help(){dialog('Práce se simulátorem',`<p><b>Součástky:</b> vyberte vlevo, kliknutím vložte do mřížky. Esc ukončí vkládání. Vybranou součástku přesuňte tažením, otočte R nebo pravým tlačítkem, hodnotu změňte v panelu Vlastnosti.</p><p><b>Vodiče:</b> Hotovo / Esc nebo pravé tlačítko ukončí rozkreslený vodič.  stiskněte W a klikněte na vývody. Spojování pokračuje z posledního bodu, Esc jej ukončí. Odbočku začněte kliknutím na stávající vodič. Křížení bez společného koncového bodu není spoj.</p><p><b>Měření:</b> připojte zem. Klávesou P přidáte napěťovou sondu. Spusťte výpočet; osciloskop posouvá časové okno vypočteného záznamu. Rychlost mění přehrávání, numerický krok určuje přesnost. Tlačítka Krok procházejí jednotlivé vzorky. Slider zdroje přepočítá celý záznam od počátečního stavu. Pozastavení zastaví přehrávání. AC karta vykreslí přenos vůči vstupnímu AC zdroji a fázi přerušovanou čarou.</p><p><b>Modely v betě:</b> soustředěné ideální RLC, modelová dioda a operační zesilovač s nastavitelným zesílením, napájecími mezemi, pásmem a slew rate. Numerické řešení používá modifikovanou uzlovou analýzu. Výpočetní krok určujete zvlášť od rychlosti animace. Zmenšením kroku ověřujte ustálení výsledku.</p><p><b>SPICE:</b> volba SPICE / ngspice provede výpočet ověřeným jádrem ngspice v samostatném vlákně. První spuštění načte přibližně 20 MB jádra (přenos je komprimovaný). Interaktivní model používá rychlou uzlovou analýzu. Číslicové bloky používají vlastní ideální logický runtime při obou volbách.</p><p><b>Diody:</b> Schottkyho dioda používá exponenciální model s jinými parametry, Zenerova dioda modeluje závěrný průraz. Tunelová dioda používá výukovou analytickou aproximaci se záporným diferenciálním odporem. Nejde o měřené modely konkrétních výrobků. OZ s vnějším napájením omezuje výstup napětím na V+ a V−; klidový odběr a odběr z napájecích pinů se nemodelují.</p><p><b>Značky:</b> použitá kresba vychází z běžných elektrotechnických konvencí. Referenční normou je IEC 60617; jednotlivé licencované listy nebyly zpřístupněné, úplná normová shoda není deklarovaná.</p><p><b>GHz:</b> AC analýzu lze nastavit do 10 GHz. Jde o matematickou odezvu zvolených modelů; parazity plošného spoje, elektromagnetické vazby a přenosové jevy nejsou zahrnuté. Beta nemá ověřenou RF přesnost.</p><p><b>Export:</b> soubor projektu lze znovu otevřít. Odkaz obsahuje samostatnou kopii bez účtu. PNG/SVG obsahuje čisté schéma a právě zobrazený graf, CSV číselná data.</p>`);}
