$$('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('#undo').onclick=undo;$('#redo').onclick=redo;$('#rotate').onclick=rotateSelected;$('#delete').onclick=deleteSelected;$('#fit').onclick=fit;$('#zoomIn').onclick=()=>zoom(1.2);$('#zoomOut').onclick=()=>zoom(1/1.2);$('#run').onclick=simulate;$('#reset').onclick=()=>{cancelSolver();stop();result=null;dcResult=null;instantResult=null;playback=0;render();};$('#new').onclick=()=>{dialog('Nový obvod','<p>Aktuální obvod můžete nejdříve uložit do souboru. Vytvoření nového obvodu lze vrátit tlačítkem Zpět.</p><div class="dialog-actions"><button id="confirmNew" class="primary">Vytvořit prázdný obvod</button><button id="saveBeforeNew">Uložit současný</button></div>');$('#confirmNew').onclick=()=>{loadProject(empty());$('#dialog').close();};$('#saveBeforeNew').onclick=()=>download(filename('shieldio'),JSON.stringify(project,null,2),'application/json');};$('#save').onclick=()=>{download(filename('shieldio'),JSON.stringify(project,null,2),'application/json');toast('Projekt uložen do souboru.');};$('#open').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>3000000)throw Error('Soubor projektu může mít nejvýše 3 MB.');loadProject(JSON.parse(await f.text()));toast('Projekt otevřen.');}catch(err){toast(err.message,true);}finally{e.target.value='';}};$('#share').onclick=share;$('#export').onclick=()=>{dialog('Export práce','<p>Čisté schéma, označení, hodnoty a právě zobrazený graf. Pro další úpravy si uložte také soubor projektu.</p><div class="dialog-actions"><button id="exportPng" class="primary">Obrázek PNG</button><button id="exportSvg">Vektor SVG</button><button id="exportCsv">Naměřená data CSV</button></div>');$('#exportPng').onclick=()=>pngExport().catch(e=>toast(e.message,true));$('#exportSvg').onclick=()=>download(filename('svg'),exportSvg(),'image/svg+xml');$('#exportCsv').onclick=exportCsv;};$('#csv').onclick=exportCsv;$('#help').onclick=help;$('#closeDialog').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog')){let r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}};$('#title').onchange=e=>{snapshot();project.title=e.target.value.trim()||'Nový obvod';changed(false);};$('#addProbe').onclick=()=>setTool('probe');
$('#properties').onchange=e=>{try{let input=e.target;if(input.id==='probeLabel'){let p=project.probes.find(p=>p.id===selected?.id);snapshot();p.label=input.value.slice(0,40);changed(false);return;}if(!input.dataset.param||selected?.kind!=='component')return;let c=project.components.find(c=>c.id===selected.id),k=input.dataset.param;let orig=c.params[k]??meta(c.type)?.defaults?.[k];let val=k==='label'?input.value.slice(0,40):k==='waveform'?input.value:typeof orig==='boolean'?input.value==='true':numeric(input.value);if(['resistor','capacitor','inductor'].includes(c.type)&&k==='value'&&val<=0)throw Error('Hodnota musí být kladná.');snapshot();c.params[k]=val;changed();}catch(err){toast(err.message,true);renderProperties();}};$('#properties').onclick=e=>{if(e.target.id==='duplicate')duplicate();if(e.target.id==='rotateSelected')rotateSelected();if(e.target.id==='removeSelected')deleteSelected();};$('#probeList').onclick=e=>{let b=e.target.closest('[data-remove-probe]');if(b){snapshot();project.probes=project.probes.filter(p=>p.id!==b.dataset.removeProbe);changed();}};
$$('[data-tab]').forEach(b=>b.onclick=()=>{stop();tab=b.dataset.tab;result=null;instantResult=null;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderSettings();renderChart();renderProperties();});$('#instrumentSettings').onchange=e=>{let k=e.target.dataset.setting;try{if(e.target.id==='engineSelect'){snapshot();project.settings.engine=e.target.value==='spice'?'spice':'mna';changed();return;}if(e.target.id==='currentSelect'){project.settings.currentId=e.target.value;renderChart();return;}if(e.target.id==='triggerLevel'){let v=e.target.value.trim();project.settings.triggerLevel=v?numeric(v):null;changed(false);return;}if(!k)return;let v=numeric(e.target.value);if(v<=0)throw Error('Nastavení musí být kladné.');snapshot();project.settings[k]=v;changed();}catch(err){toast(err.message,true);renderSettings();}};$('#instrumentSettings').onclick=e=>{if(e.target.id==='analyze'){stop();dirty=true;simulate();}};
$('#propertiesToggle').onclick=()=>{let opened=$('.inspector').classList.toggle('mobile-open');$('#propertiesToggle').setAttribute('aria-expanded',String(opened));};const inspectorClose=document.createElement('button');inspectorClose.className='inspector-close';inspectorClose.textContent='Zavřít';inspectorClose.onclick=()=>{$('.inspector').classList.remove('mobile-open');$('#propertiesToggle').setAttribute('aria-expanded','false');};$('.inspector .panel-heading').append(inspectorClose);
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||$('#dialog').open)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('#save').click();return;}if(e.key==='Escape'){setTool('select');selected=null;render();}if(e.key.toLowerCase()==='w')setTool('wire');if(e.key.toLowerCase()==='v')setTool('select');if(e.key.toLowerCase()==='p')setTool('probe');if(e.key.toLowerCase()==='r')rotateSelected();if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();}if(e.code==='Space'){e.preventDefault();simulate();}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate();}});
