async function init(){try{let fromHash=await readHash();if(!fromHash){let saved=localStorage.getItem(storageKey);if(saved)try{project=validateProject(JSON.parse(saved));}catch{}else if(examples[0])project=validateProject(clone(examples[0].project));}}catch(e){toast(e.message,true);}renderLibrary();render();requestAnimationFrame(fit);workspaceMode=modeOf(project);applyMode();showModeChooser();}
function applyMode(){document.body.dataset.mode=workspaceMode;$('#modeSwitch').textContent=modeNames[workspaceMode]+' ▾';$$('[data-tab]').forEach(b=>b.hidden=workspaceMode!=='analog'&&b.dataset.tab!=='scope');if(workspaceMode!=='analog'&&tab!=='scope'){tab='scope';result=null;}$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));renderLibrary();}
function showModeChooser(){stop();dialog('Co chcete dnes sestavit?',`<p>Každý režim má vlastní součástky a vzorová zapojení. Rozpracované projekty se ukládají zvlášť.</p><div class="mode-choices">${[['analog','01','Elektrické obvody','Zdroje, RLC, diody, zesilovače. Napětí, proudy a frekvenční charakteristiky.'],['digital','02','Číslicová technika','Hradla, klopné obvody, registry a čítače. Časové průběhy logických stavů.'],['fbd','03','FBD bloky','Logické funkce, paměti a časovače. Vstup přepnete dvojklikem.']].map(([id,n,title,description])=>`<button data-mode="${id}"><small>${n}</small><strong>${title}</strong><span>${description}</span></button>`).join('')}</div>`);$('#closeDialog').hidden=true;$('#dialog').oncancel=e=>{e.preventDefault();};$$('button[data-mode]').forEach(b=>b.onclick=()=>{let next=b.dataset.mode;if(next!==workspaceMode){try{localStorage.setItem(storageKey+'-'+workspaceMode,JSON.stringify(project));}catch{}let saved=localStorage.getItem(storageKey+'-'+next);workspaceMode=next;let ex=examples.find(e=>e.mode===next);let p=saved?JSON.parse(saved):ex?clone(ex.project):empty();p.mode=next;loadProject(p);}applyMode();$('#dialog').close();$('#closeDialog').hidden=false;$('#dialog').oncancel=null;render();setTimeout(fit,50);});}
$('#modeSwitch').onclick=showModeChooser;$('#menuHelp').onclick=help;
$('#endWire').onclick=()=>setTool('select');
$('#themeToggle').onclick=()=>{let dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('shieldio-sim-theme',dark?'dark':'light');$('#themeToggle').textContent=dark?'Světlý režim':'Tmavý režim';};
document.documentElement.dataset.theme=localStorage.getItem('shieldio-sim-theme')||'light';$('#themeToggle').textContent=document.documentElement.dataset.theme==='dark'?'Světlý režim':'Tmavý režim';
$('#playSpeed').onchange=e=>{playSpeed=Number(e.target.value)||1;};
function stepSample(direction){stop();if(!result?.time?.length)return toast('Nejprve spusťte simulaci.');playback=Math.max(0,Math.min(result.time.at(-1),playback+direction*(result.step||project.settings.step)));showSample();}
$('#stepBack').onclick=()=>stepSample(-1);$('#stepNext').onclick=()=>stepSample(1);
svg.addEventListener('contextmenu',e=>{e.preventDefault();if(wireStart||placing){setTool('select');return;}let c=e.target.closest('[data-component]');if(c){selected={kind:'component',id:c.dataset.component};rotateSelected();}});
$('#properties').oninput=e=>{if(e.target.id!=='liveVoltage')return;let c=project.components.find(c=>c.id===selected?.id);if(!c)return;let resume=running;let value=Number(e.target.value);$('#liveValue').textContent=fmt(value,'V');clearTimeout(liveTimer);liveTimer=setTimeout(async()=>{snapshot();c.params.value=value;stop();result=null;dirty=true;await simulate();if(!resume)stop();},180);};

init();
